const docs = [
  { source: 'Runbook: Phishing Email Triage', text: 'Phishing email triage. Trigger: user- or gateway-reported suspicious email/URL/attachment. Steps: verify sender and SPF/DKIM/DMARC; detonate URLs with urlscan.io; check indicators against threat intel (MISP); look for credential-harvesting pages. Severity: medium by default; raise to high if users clicked or submitted credentials, or the domain is confirmed malicious. Actions: quarantine and purge the email from all mailboxes, block the domain/URL at gateway and proxy, sweep for other recipients, and force password reset + session revocation for anyone who submitted credentials.' },
  { source: 'Runbook: Ransomware Active Incident', text: 'Ransomware active incident. Trigger: EDR confirms active encryption or ransomware behavior on one or more hosts. Severity: CRITICAL, especially when multiple hosts, a domain controller, or data exfiltration are involved. Actions: isolate affected hosts via EDR (do NOT power off - preserve memory), block C2 domains/IPs, preserve forensic evidence (memory + disk images), rotate/disable privileged and domain credentials from a trusted system, verify and isolate backups (do not restore until cleared), and immediately engage the IR team, leadership, and legal.' },
  { source: 'Runbook: Malicious IP / C2 Beacon', text: 'Malicious IP or C2 beacon. Trigger: outbound connection to a known-malicious IP/domain or Cobalt Strike beaconing detected. Steps: enrich the indicator with threat intel (MISP) and passive DNS; confirm the beaconing pattern in EDR/network logs. Severity: high when beaconing is confirmed, critical if on a critical asset or with lateral movement. Actions: isolate the host, block the IOC at perimeter and DNS, hunt for additional beacons and lateral movement, and identify the initial access vector.' },
  { source: 'Runbook: Account Compromise', text: 'Account compromise. Trigger: impossible-travel logins, MFA fatigue, or anomalous authentication. Severity: high, critical for privileged or domain accounts. Actions: disable the account, revoke active sessions and refresh/OAuth tokens, force a password reset, reset MFA methods, and review authentication and audit logs for scope and lateral movement.' },
  { source: 'Runbook: Malware / EDR Detection', text: 'Malware detection from EDR. Trigger: endpoint protection flags malware on a host. Steps: quarantine the host, collect the sample and hashes, check reputation (VirusTotal/MISP), and determine scope. Severity: medium for a single contained low-value host; high or critical when multiple hosts or a critical asset are affected. Actions: remediate or reimage the host, block the hash/IOCs fleet-wide, and hunt for related infections.' },
  { source: 'Runbook: Severity Classification Matrix', text: 'Severity classification matrix. LOW: single low-value asset, no confirmed compromise, easily contained. MEDIUM: suspicious but unconfirmed activity, limited scope, no sensitive data. HIGH: confirmed compromise, sensitive data at risk, or spread across several hosts. CRITICAL: active, widespread incident - ransomware encryption, domain controller or critical-infrastructure compromise, or active data exfiltration. When evidence is mixed or unavailable, choose the more conservative (higher) severity.' },
  { source: 'Runbook: Escalation Criteria', text: 'Escalation criteria. Open a TheHive case and escalate to Tier-2/IR when any of these are true: confirmed compromise, multiple affected hosts, a privileged or domain-controller account involved, data exfiltration, or any ransomware activity. For low-risk, unconfirmed, single-host events with no sensitive data, auto-close with documentation and monitoring. Always preserve evidence and record actions in the ticket.' }
];
return docs.map((d) => ({ json: { text: d.text, source: d.source }, pairedItem: { item: 0 } }));
